// Colors below were migrated from saved paint into code via api.paint.*
// (the model is now self-colouring; see /ai/colors.md). Edit colours here.
const __pwModel = (() => {
const { Manifold, CrossSection, label } = api;

// =====================================================================
// PAC-MAN + GHOST diorama. Z-up, front faces -Y. ONE watertight solid.
// Pac-Man: clean yellow wedge sphere (mouth opens toward +X, the pellets/ghost,
//          tilted slightly toward -Y so it reads from the front camera).
// Ghost:   domed top, straight body, classic WAVY SCALLOPED skirt,
//          white oval eyes with blue pupils (both looking -Y/left-ish).
// Both fused to a slim rounded base; pellet dots between them.
// =====================================================================

// ---------- PAC-MAN ----------
const PAC_R = 8.5;
const PAC_X = -13;
const PAC_Z = PAC_R + 0.5; // lifted so it rests on the base

const pacSphere = Manifold.sphere(PAC_R, 64).translate([PAC_X, 0, PAC_Z]);

// Mouth wedge: triangle in XY extruded along Z, apex at Pac-Man center,
// opening toward the ghost (+X) and slightly toward the viewer (-Y) so the
// iconic open mouth reads in the 3/4 catalog view. ~33° half-angle.
const mouthHalfAngle = 33 * Math.PI / 180;
const reach = PAC_R + 3;
// Direction the mouth opens: toward the pellets/ghost (+X), a touch toward -Y so
// it still reads from the front camera (~-8.5 deg).
const dir = Math.atan2(-0.15, 1.0); // bisector angle in XY
const a1 = dir - mouthHalfAngle;
const a2 = dir + mouthHalfAngle;
const mouthProfile = [
  [PAC_X, 0],
  [PAC_X + reach * Math.cos(a1), reach * Math.sin(a1)],
  [PAC_X + reach * Math.cos(a2), reach * Math.sin(a2)],
];
const mouthWedge = Manifold.extrude(CrossSection.ofPolygons([mouthProfile]), PAC_R * 2 + 6)
  .translate([0, 0, PAC_Z - (PAC_R + 3)]);

const pacman = label(pacSphere.subtract(mouthWedge), 'pacman');

// Pac-Man eye: a small dark dot on the upper front of the head, outside the mouth
// wedge, centre 8.3 from the sphere centre so it sits ON the r8.5 surface (~0.7 proud).
const pacEye = label(
  Manifold.sphere(0.9, 24).translate([PAC_X + 1.2, -4.6, PAC_Z + 6.8]),
  'paceye'
);

// ---------- GHOST ----------
const GH_X = 13;
const GH_R = 7.0; // body radius
const SKIRT_Z = 1.4; // z where the skirt lobes bottom out (0.1 below BASE_TOP = 1.5, so they fuse into the base)
const BODY_TOP = 18.5; // top of the dome

// Dome top: a sphere whose center is placed so its top reaches BODY_TOP.
const domeC = BODY_TOP - GH_R; // dome center z
const dome = Manifold.sphere(GH_R, 64).translate([GH_X, 0, domeC]);

// Straight body: cylinder from the hem line up into the dome (overlaps it).
// The hem (cylinder bottom) sits a few units up so the scalloped teeth hang
// below it as distinct lobes with clear concave notches between them.
const hemZ = SKIRT_Z + 4.2;
const bodyCyl = Manifold.cylinder(domeC - hemZ + 1.0, GH_R, GH_R, 64)
  .translate([GH_X, 0, hemZ]);

let ghostBody = dome.add(bodyCyl);

// Classic WAVY SCALLOPED skirt, all the way around the hem: a solid core
// (so the ghost sits flat on the base with no hidden cavity) ringed by
// NUM_TEETH round-bottomed lobes whose outer edge is flush with the body wall.
// Adjacent lobes overlap slightly, so the cusps between them read as the
// concave notches of the scalloped hem from every side.
const NUM_TEETH = 8;
const toothR = 2.1;
const ringR = GH_R - toothR; // lobe-centre radius (outer edge flush with the wall)
const toothBotZ = SKIRT_Z + toothR; // sphere cap centre
const toothTopZ = hemZ + 1.2; // overlap up into the body
let teeth = Manifold.cylinder(toothTopZ - SKIRT_Z, ringR, ringR, 64)
  .translate([GH_X, 0, SKIRT_Z]);
for (let i = 0; i < NUM_TEETH; i++) {
  const ang = (i / NUM_TEETH) * Math.PI * 2;
  const bx = GH_X + ringR * Math.cos(ang);
  const by = ringR * Math.sin(ang);
  const col = Manifold.cylinder(toothTopZ - toothBotZ, toothR, toothR, 32)
    .translate([bx, by, toothBotZ]);
  const cap = Manifold.sphere(toothR, 32).translate([bx, by, toothBotZ]);
  teeth = teeth.add(col).add(cap);
}
ghostBody = ghostBody.add(teeth);

// Flatten the very bottoms flush so the ghost sits on the base.
const cutter = Manifold.cube([GH_R * 4, GH_R * 4, 8], true)
  .translate([GH_X, 0, SKIRT_Z - 4]);
ghostBody = label(ghostBody.subtract(cutter), 'ghost');

// ---------- GHOST EYES (white ovals) + PUPILS (blue), both looking -Y/left ----------
// Each eye is built in a local frame (front = -Y) and rotated so it lies TANGENT
// to the dome at its azimuth/elevation, so the outer rim of every eye stays
// buried in the dome instead of standing off it like a flap.
const EYE_AZ = 21; // degrees outward from straight ahead (-Y)
const EYE_EL = Math.asin(0.15) * 180 / Math.PI; // elevation above the dome centre
const EYE_RAD = GH_R - 0.6; // eye centre sits just inside the dome surface
const azR = EYE_AZ * Math.PI / 180, elR = EYE_EL * Math.PI / 180;

const PUPIL_OFF = [-0.5, -1.4, -0.4]; // world offset: pupil centre - eye centre
function eyeAt(side) {
  const az = side * azR;
  const c = [
    GH_X + EYE_RAD * Math.sin(az) * Math.cos(elR),
    -EYE_RAD * Math.cos(az) * Math.cos(elR),
    domeC + EYE_RAD * Math.sin(elR),
  ];
  const rot = [-EYE_EL, 0, side * EYE_AZ];
  // Oval eye = a sphere scaled wider in X & taller in Z, flatter in Y.
  const ball = Manifold.sphere(1.0, 32).scale([2.0, 1.4, 2.6]).rotate(rot).translate(c);
  // Blue pupil: r 0.7, placed with the SAME WORLD offset from its eye centre for
  // both eyes (0.5 toward -X = looking left, 0.4 down, 1.4 forward along -Y), so both
  // pupils look the same way regardless of each eye's tilt. Front of the pupil
  // stands ~0.4 (right eye) to ~0.7 (left eye) proud of the eye surface.
  const pupil = Manifold.sphere(0.7, 24).translate([
    c[0] + PUPIL_OFF[0], c[1] + PUPIL_OFF[1], c[2] + PUPIL_OFF[2],
  ]);
  return { ball, pupil, c };
}
const eyeL = eyeAt(-1), eyeR = eyeAt(1);
// (verified: pupil centre - eye centre is PUPIL_OFF for both eyes by construction)
const eyes = label(eyeL.ball.add(eyeR.ball), 'eyes');
const pupils = label(eyeL.pupil.add(eyeR.pupil), 'pupils');

// ---------- PELLET DOTS between the two characters ----------
const pelletZ = 1.6;

function pellet(x) {
  return Manifold.sphere(1.1, 24).translate([x, 0, pelletZ + 0.5]);
}
const pellets = label(pellet(-3.2).add(pellet(0)).add(pellet(3.2)), 'pellets');

// ---------- SLIM ROUNDED BASE ----------
// Stadium slab = hull of two disks, one under each figure. Top at z = 1.5 so it
// overlaps the bottoms of both the ghost skirt and Pac-Man's lower cap.
const BASE_TOP = 1.5;
const BASE_BOT = -1.0;
const BASE_H = BASE_TOP - BASE_BOT;
const baseR = 10.0;
const baseDiskPac = Manifold.cylinder(BASE_H, baseR, baseR, 64).translate([PAC_X, 0, BASE_BOT]);
const baseDiskGhost = Manifold.cylinder(BASE_H, baseR, baseR, 64).translate([GH_X, 0, BASE_BOT]);
const base = label(baseDiskPac.add(baseDiskGhost).hull(), 'base');

// ---------- ASSEMBLE ----------
// Lift everything so the underside of the base rests on z = 0.
return base
  .add(pacman)
  .add(pacEye)
  .add(ghostBody)
  .add(eyes)
  .add(pupils)
  .add(pellets)
  .translate([0, 0, -BASE_BOT]);
})();
api.paint.label("pacman", [1, 0.85, 0.05]);
api.paint.label("paceye", [0.08, 0.06, 0.04]);
api.paint.label("ghost", [0.96, 0.16, 0.2]);
api.paint.label("eyes", [1, 1, 1]);
api.paint.label("pupils", [0.15, 0.3, 0.95]);
api.paint.label("pellets", [1, 0.78, 0.55]);
api.paint.label("base", [0.12, 0.13, 0.2]);
return __pwModel;
